','e9d93e66-b295-4939-9e20-4eb7c4e16e59','ebb7513e-36bb-4a11-9099-f6c68176385d','ee7f9208-e83d-46aa-a200-a3198e7baba8','ee8272dd-c664-4fe1-a9c9-71a060f3fcce','ef30e0a2-5dca-459c-b205-441b4cb49dda','f12e141c-7c64-4cde-86be-0fb363433ac8','f31a38aa-de3b-41da-92e8-07130eedd724','f71d1c05-a525-4069-aa01-0397bd4d8e0d','f802bfbc-3da1-4798-8590-484fa386e734','f8524f73-d8b3-43bf-bc68-dcbffad6812d','f9e9967c-9f4d-4401-9120-0c4432669e2a','fa9987c1-b3d4-49db-bc5e-199ed93dd16c','fa9e8cad-5f7b-415f-966d-e28348e4d3b1','fd31fd9a-e7d7-4e4a-9784-3bb74eb5e0fd','fdd4b884-236d-4701-b923-0e819052da9c']::uuid[];
  v_count integer;
  v_amount numeric;
  v_id uuid;
  v_value numeric;
  v_r jsonb;
  v_n integer:=0;
  v_sum numeric:=0;
  v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
  IF to_regprocedure('public.fn_ca_pay_closed_target_ticket_in_cash(uuid,text)') IS NULL THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_DOOR_MISSING: apply 20261012054804 first';
  END IF;
  SELECT count(*), COALESCE(sum(tk.value),0) INTO v_count,v_amount
    FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-24 17:45:30+00' AND tk.created_at<'2026-10-13 00:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id);
  IF v_count<>168 OR v_amount<>11160.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_PREIMAGE_CHANGED: part 5 has % tickets worth %',v_count,v_amount;
  END IF;
  FOR v_id,v_value IN
    SELECT tk.id,tk.value FROM public.tournament_tickets tk
     WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-24 17:45:30+00' AND tk.created_at<'2026-10-13 00:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)
     ORDER BY tk.created_at,tk.id
  LOOP
    v_r:=public.fn_ca_pay_closed_target_ticket_in_cash(v_id,'stranded_ticket_settlement_20261012');
    IF COALESCE((v_r->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_r->>'replayed')::boolean,false)
       OR (v_r->>'amount')::numeric IS DISTINCT FROM v_value THEN
      RAISE EXCEPTION 'STRANDED_TICKET_CASH_REFUSED: %',v_r;
    END IF;
    v_n:=v_n+1;
    v_sum:=round(v_sum+v_value,2);
    v_ids:=v_ids||v_id;
  END LOOP;
  IF v_n<>168 OR v_sum<>11160.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: paid % tickets worth %',v_n,v_sum;
  END IF;
  IF (SELECT count(*) FROM public.tournament_tickets tk
       WHERE tk.id=ANY(v_ids) AND tk.status='redeemed'
         AND tk.redeemed_at=transaction_timestamp())<>v_n
     OR (SELECT COALESCE(sum(l.amount),0)
           FROM public.chip_ledger_idem i JOIN public.chip_ledger l ON l.id=i.leg_id
          WHERE i.idempotency_key IN (
            SELECT 'ticket:'||x::text||':closed-target-cash' FROM unnest(v_ids) x)
            AND l.from_type='escrow' AND l.to_type='player_wallet'
            AND l.category='ticket_redeem')<>v_sum
     OR EXISTS (SELECT 1 FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-24 17:45:30+00' AND tk.created_at<'2026-10-13 00:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)) THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: receipts disagree for % tickets worth %',v_n,v_sum;
  END IF;
  RAISE NOTICE 'stranded satellite tickets paid in cash, part 5: % tickets worth %',v_n,v_sum;
END
$settle$;
COMMIT;
